<?php require 'config/bootstrap.php'; require_login(); $f=$_GET['f']??'open';
$w=['open'=>"o.status IN('pending','in_progress')",'overdue'=>"o.status IN('pending','in_progress') AND o.due_date<CURDATE()",'done'=>"o.status='completed'",'all'=>'1=1'][$f]??'1=1';
$s=db()->prepare("SELECT o.*,c.title FROM obligations o JOIN contracts c ON c.id=o.contract_id WHERE c.user_id=? AND $w ORDER BY o.due_date IS NULL,o.due_date");$s->execute([uid()]);$r=$s->fetchAll();
page_head('Obligations'); ?><h1 class="h3 mb-3">Obligations</h1><div class="mb-3"><?php foreach(['open','overdue','done','all'] as $x):?><a class="btn btn-sm <?=$f===$x?'btn-primary':'btn-outline-light'?>" href="?f=<?=$x?>"><?=$x?></a> <?php endforeach;?></div>
<div class="cardx table-responsive"><?php if(!$r):?><div class="empty">Nothing here.</div><?php else:?><table class="table"><tr><th>Obligation</th><th>Contract</th><th>Due</th><th>Status</th></tr><?php foreach($r as $x):?><tr><td><?=e($x['description'])?></td><td><a href="contract.php?id=<?=$x['contract_id']?>"><?=e($x['title'])?></a></td><td><?=e($x['due_date']?:'—')?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table><?php endif;?></div><?php page_foot();
